// Inlined Base64 Image Assets for Slimmers Club
const CLUB_IMAGES = {
  hero: "data:image/jpeg;base64,",
  studio: "data:image/jpeg;base64,"
};

document.addEventListener('DOMContentLoaded', () => {
  const heroImg = document.getElementById('hero-gym-image');
  if (heroImg) heroImg.src = CLUB_IMAGES.hero;
  
  const studioImg = document.getElementById('studio-gym-image');
  if (studioImg) studioImg.src = CLUB_IMAGES.studio;
});
